"use client"

import type { ComponentProps } from "react"
import { mergeProps } from "@base-ui/react/merge-props"
import { useRender } from "@base-ui/react/use-render"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"

import { Separator } from "@/registry/react/separator"

// NOTE: Update these paths if needed
import "../tokens.css"
import "./button-group.css"

const buttonGroupVariants = cva("np-button-group", {
  variants: {
    orientation: {
      horizontal: "",
      vertical: "np-button-group-vertical",
    },
  },
  defaultVariants: {
    orientation: "horizontal",
  },
})

function ButtonGroup({
  className,
  orientation = "horizontal",
  ...props
}: ComponentProps<"div"> & VariantProps<typeof buttonGroupVariants>) {
  return (
    <div
      role="group"
      data-slot="button-group"
      data-orientation={orientation}
      className={cn(buttonGroupVariants({ orientation }), className)}
      {...props}
    />
  )
}

function ButtonGroupText({
  className,
  render,
  ...props
}: useRender.ComponentProps<"div">) {
  return useRender({
    defaultTagName: "div",
    render,
    props: mergeProps<"div">(
      {
        className: cn("np-button-group-text", className),
      },
      props
    ),
    state: {
      slot: "button-group-text",
    },
  })
}

function ButtonGroupSeparator({
  className,
  orientation = "vertical",
  ...props
}: React.ComponentProps<typeof Separator>) {
  return (
    <Separator
      data-slot="button-group-separator"
      orientation={orientation}
      className={(state) =>
        cn(
          "np-button-group-separator",
          typeof className === "function" ? className(state) : className
        )
      }
      {...props}
    />
  )
}

export {
  ButtonGroup,
  ButtonGroupSeparator,
  ButtonGroupText,
  buttonGroupVariants,
}

/* nepui — Button Group */

.np-button-group,
[data-np-button-group] {
  display: flex;
  width: fit-content;
  align-items: stretch;
}

:is(.np-button-group, [data-np-button-group]):is(
  .np-button-group-vertical,
  [data-orientation="vertical"]
) {
  flex-direction: column;
}

:is(.np-button-group, [data-np-button-group]):has(
  > :is(.np-button-group, [data-np-button-group])
) {
  gap: 0.5rem;
}

:is(.np-button-group, [data-np-button-group]) > :focus-visible {
  position: relative;
  z-index: 10;
}

:is(.np-button-group, [data-np-button-group])
  > :is(input, .np-input, [data-np-input]) {
  flex: 1;
}

/* Horizontal */
:is(.np-button-group, [data-np-button-group]):not(
    .np-button-group-vertical,
    [data-orientation="vertical"]
  )
  > :not(:last-child) {
  border-start-end-radius: 0;
  border-end-end-radius: 0;
}

:is(.np-button-group, [data-np-button-group]):not(
    .np-button-group-vertical,
    [data-orientation="vertical"]
  )
  > :not(:first-child) {
  border-start-start-radius: 0;
  border-end-start-radius: 0;
  border-inline-start-width: 0;
}

/* Vertical */
:is(.np-button-group, [data-np-button-group]):is(
    .np-button-group-vertical,
    [data-orientation="vertical"]
  )
  > :not(:last-child) {
  border-end-start-radius: 0;
  border-end-end-radius: 0;
}

:is(.np-button-group, [data-np-button-group]):is(
    .np-button-group-vertical,
    [data-orientation="vertical"]
  )
  > :not(:first-child) {
  border-start-start-radius: 0;
  border-start-end-radius: 0;
  border-block-start-width: 0;
}

:is(.np-button-group, [data-np-button-group])
  :is(
    .np-button-xs,
    .np-button-sm,
    .np-button-icon-xs,
    .np-button-icon-sm,
    :is(.np-button, [data-np-button])[data-size="xs"],
    :is(.np-button, [data-np-button])[data-size="sm"],
    :is(.np-button, [data-np-button])[data-size="icon-xs"],
    :is(.np-button, [data-np-button])[data-size="icon-sm"]
  ) {
  --np-button-radius: var(--np-radius-md);
}

/* Text */

.np-button-group-text,
[data-np-button-group-text] {
  display: flex;
  align-items: center;
  box-sizing: border-box;
  gap: 0.5rem;
  padding: 0 0.625rem;

  border: 1px solid var(--np-border);
  border-radius: var(--np-radius-md);
  background: var(--np-muted);

  font: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
}

:is(.np-button-group-text, [data-np-button-group-text]) svg {
  flex-shrink: 0;
  pointer-events: none;
}

:is(.np-button-group-text, [data-np-button-group-text])
  svg:not([class*="size-"]) {
  width: 1rem;
  height: 1rem;
}

/* Separator */

.np-button-group-separator,
[data-np-button-group-separator] {
  position: relative;
  flex-shrink: 0;
  align-self: stretch;
  box-sizing: border-box;
  width: 1px;
  height: auto;
  margin: 1px 0;
  border: 0;
  background: var(--np-input, var(--np-border));
}

:is(.np-button-group-separator, [data-np-button-group-separator]):is(
  .np-button-group-separator-horizontal,
  [data-orientation="horizontal"]
) {
  width: auto;
  height: 1px;
  margin: 0 1px;
}
